  if(!preg_match('/^[A-Z0-9_-]{4,60}$/',$student))$error='Student ID must contain 4–60 letters, numbers, dashes, or underscores.';elseif($name==='')$error='Complete name is required.';elseif($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Enter a valid email address.';elseif($course===''||$year===''||$section==='')$error='Course, year level, and section are required.';elseif(strlen($password)<8)$error='New password must contain at least 8 characters.';elseif($password!==$confirm)$error='New passwords do not match.';else{$qr=$attendee['qr_token']?:bin2hex(random_bytes(24));$ok=pg_query_params($conn,"UPDATE attendees SET attendee_code=$1,student_number=$1,id_card_number=COALESCE(id_card_number,$1),full_name=$2,email=$3,phone=$4,course=$5,year_level=$6,section=$7,organization=concat_ws(' · ',$5,$6,$7),password_hash=$8,qr_token=$9,must_complete_profile=FALSE,account_status='active',credentials_updated_at=NOW(),updated_at=NOW() WHERE id=$10",[$student,$name,$email?:null,$phone?:null,$course,$year,$section,password_hash($password,PASSWORD_DEFAULT),$qr,$_SESSION['attendee_id']]);if($ok){$_SESSION['attendee_code']=$student;$_SESSION['attendee_name']=$name;$_SESSION['must_complete_profile']=false;$_SESSION['attendance_message']='Profile completed. Your permanent attendance QR is now ready.';redirect('dashboard.php');}$error='That student ID is already registered. Please check the value or contact an administrator.';}
