phone']??'')?>"></div><div class="field"><label>Course / Program</label><input name="course" required value="<?=h($_POST['course']??'')?>" placeholder="BSIT"></div><div class="field"><label>Year level</label><input name="year_level" required value="<?=h($_POST['year_level']??'')?>" placeholder="3rd Year"></div><div class="field full"><label>Section</label><input name="section" required value="<?=h($_POST['section']??'')?>" placeholder="Section A"></div><div class="field"><label>New password</label><input type="password" name="new_password" required minlength="8" autocomplete="new-password"></div><div class="field"><label>Confirm new password</label><input type="password" name="confirm_password" required minlength="8" autocomplete="new-password"></div><div class="field full"><button class="participant-submit" style="width:100%;justify-content:center"><i class="fas fa-circle-check"></i> Save Profile and Create My QR</button></div></form></div><footer class="participant-footer">Your temporary login will stop working after this step.</footer></div></div></body></html>
